def transform(grid):
    rows_with_nonzero = set()
    num_cols = len(grid[0]) if grid else 0
    for r in range(len(grid)):
        for c in range(num_cols):
            if grid[r][c] != 0:
                rows_with_nonzero.add(r)
                break

    if not rows_with_nonzero:
        return [row[:] for row in grid]

    output = [row[:] for row in grid]
    min_row = min(rows_with_nonzero)
    max_row = max(rows_with_nonzero)

    for r in range(len(grid)):
        if all(grid[r][c] == 0 for c in range(num_cols)):
            if min_row < r < max_row:
                output[r] = [3] * num_cols

    return output
